def transform(grid):
    h,w=len(grid),len(grid[0])
    vr=[r for r in range(h) if all(grid[r][c]==3 for c in range(w))]
    vc=[c for c in range(w) if all(grid[r][c]==3 for r in range(h))]
    cr=vr[0]; cc=vc[0]
    out=[row[:] for row in grid]
    d=2
    while cr-d>=0 or cr+d<h or cc-d>=0 or cc+d<w:
        top,bot,left,right=cr-d,cr+d,cc-d,cc+d
        for c in range(max(left,0),min(right,w-1)+1):
            for r in (top,bot):
                if 0<=r<h and grid[r][c]!=3: out[r][c]=4
        for r in range(max(top,0),min(bot,h-1)+1):
            for c in (left,right):
                if 0<=c<w and grid[r][c]!=3: out[r][c]=4
        d+=2
    return out

